mapper.select:
SELECT COUNT(*)
FROM sales_order so
WHERE so.deleted = FALSE
AND so.status = 'CONFIRMED'
AND so.confirmed_at >= #{startTime}
AND so.confirmed_at < #{endTime}

SELECT COALESCE(SUM(so.settlement_total_amount), 0)
FROM sales_order so
WHERE so.deleted = FALSE
AND so.status = 'CONFIRMED'
AND so.confirmed_at >= #{startTime}
AND so.confirmed_at < #{endTime}

SELECT COALESCE(SUM(so.ordered_total_amount), 0)
FROM sales_order so
WHERE so.deleted = FALSE
AND so.status = 'CONFIRMED'
AND so.created_at >= #{startTime}
AND so.created_at < #{endTime}

SELECT COUNT(DISTINCT so.customer_id)
FROM sales_order so
WHERE so.deleted = FALSE
AND so.status = 'CONFIRMED'
AND so.confirmed_at >= #{startTime}
AND so.confirmed_at < #{endTime}

SELECT so.customer_name_snapshot AS name,
COALESCE(SUM(so.settlement_total_amount), 0) AS amount
FROM sales_order so
WHERE so.deleted = FALSE
AND so.status = 'CONFIRMED'
AND so.confirmed_at >= #{startTime}
AND so.confirmed_at < #{endTime}

GROUP BY so.customer_id, so.customer_name_snapshot
ORDER BY amount DESC
LIMIT #{limit}

SELECT COUNT(*)
FROM inventory_movement m
WHERE m.deleted = FALSE
AND m.movement_type IN
#{mt}
AND m.occurred_at >= #{startTime}
AND m.occurred_at < #{endTime}

SELECT COUNT(*)
FROM purchase_order po
WHERE po.deleted = FALSE
AND po.created_at >= #{startTime}
AND po.created_at < #{endTime}

SELECT COALESCE(SUM(po.total_amount), 0)
FROM purchase_order po
WHERE po.deleted = FALSE
AND po.created_at >= #{startTime}
AND po.created_at < #{endTime}

SELECT COUNT(*)
FROM purchase_receipt pr
WHERE pr.deleted = FALSE
AND pr.created_at >= #{startTime}
AND pr.created_at < #{endTime}

SELECT COUNT(DISTINCT po.supplier_id)
FROM purchase_order po
WHERE po.deleted = FALSE
AND po.created_at >= #{startTime}
AND po.created_at < #{endTime}
